const PI:f64=3.14159265358979323846264338327950288;
export fn lamberts_ellipsoidal_distance(v:[*]const i64,n:usize)callconv(.c)f64{if(n!=4)return -1.0e300;if(v[0]< -90000000 or v[0]>90000000 or v[2]< -90000000 or v[2]>90000000 or v[1]< -180000000 or v[1]>180000000 or v[3]< -180000000 or v[3]>180000000)return -1.0e300;if(v[0]==v[2] and v[1]==v[3])return -1.0e300;const lat1=@as(f64,@floatFromInt(v[0]))/1e6;const lon1=@as(f64,@floatFromInt(v[1]))/1e6;const lat2=@as(f64,@floatFromInt(v[2]))/1e6;const lon2=@as(f64,@floatFromInt(v[3]))/1e6;const p1=lat1*PI/180;const p2=lat2*PI/180;const l1=lon1*PI/180;const l2=lon2*PI/180;const h=@sqrt(@sin((p2-p1)/2)*@sin((p2-p1)/2)+@cos(p1)*@cos(p2)*@sin((l2-l1)/2)*@sin((l2-l1)/2));if(h==0)return -1.0e300;const sigma=2*@asin(h);const f=(6378137.0-6356752.314245)/6378137.0;const b1=@atan((1-f)*@tan(lat1*PI/180));const b2=@atan((1-f)*@tan(lat2*PI/180));const p=(b1+b2)/2;const q=(b2-b1)/2;const x=(sigma-@sin(sigma))*((@sin(p)*@sin(p)*@cos(q)*@cos(q))/(@cos(sigma/2)*@cos(sigma/2)));const y=(sigma+@sin(sigma))*((@cos(p)*@cos(p)*@sin(q)*@sin(q))/(@sin(sigma/2)*@sin(sigma/2)));return 6378137.0*(sigma-(f/2)*(x+y));}
